"""Checks on the Axon app icons generated by scripts/gen_icons.py."""

from __future__ import annotations

import importlib.util
import re
import xml.etree.ElementTree as ET
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parent.parent
THEME = ROOT / "theme" / "axon-icons"
SVG_NS = "{http://www.w3.org/2000/svg}"


def _gen():
    spec = importlib.util.spec_from_file_location("gen_icons", ROOT / "scripts" / "gen_icons.py")
    assert spec and spec.loader
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


GEN = _gen()


def test_icons_are_up_to_date() -> None:
    stale = GEN.stale(GEN.generate())
    assert not stale, f"run python3 scripts/gen_icons.py (stale: {[str(p) for p in stale]})"


@pytest.mark.parametrize("name", GEN.ICONS)
def test_colour_icon_is_valid_svg_on_the_shared_grid(name: str) -> None:
    root = ET.parse(THEME / "scalable" / "apps" / f"{name}.svg").getroot()
    assert root.get("viewBox") == "0 0 128 128"
    assert root.find(f"{SVG_NS}title") is not None  # a name for screen readers


@pytest.mark.parametrize("name", GEN.ICONS)
def test_symbolic_icon_uses_fills_only(name: str) -> None:
    """GTK recolours symbolic icons through their fill, so strokes would stay grey."""
    path = THEME / "symbolic" / "apps" / f"{name}-symbolic.svg"
    root = ET.parse(path).getroot()
    assert root.get("viewBox") == "0 0 16 16"
    text = path.read_text()
    assert "stroke" not in text
    assert set(re.findall(r'fill="([^"]+)"', text)) == {GEN.SYMBOLIC_FILL}


def test_every_axon_desktop_file_uses_an_axon_icon() -> None:
    files = sorted((ROOT / "data" / "applications").glob("*.desktop"))
    files.append(ROOT / "apex-win" / "scripts" / "apex-win.desktop")
    for desktop in files:
        icon = re.search(r"^Icon=(.+)$", desktop.read_text(), re.M)
        assert icon, desktop
        assert icon.group(1) in GEN.ICONS, f"{desktop.name}: Icon={icon.group(1)}"


def test_icon_theme_lists_its_directories() -> None:
    index = (THEME / "index.theme").read_text()
    dirs = re.search(r"^Directories=(.+)$", index, re.M)
    assert dirs
    for d in dirs.group(1).split(","):
        assert (THEME / d).is_dir(), d
        assert f"[{d}]" in index
